INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann eine Präfixlänge von /128 für ein Subnetz mit mehreren Geräten verwendet werden?', 2, '[{"text": "Nein", "correct": true, "because": "/128 definiert eine einzelne Adresse"}, {"text": "Ja", "correct": false, "because": "Keine Hosts bei /128 möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Präfixlänge bei IPv6 immer in der CIDR-Notation angegeben?', 2, '[{"text": "Ja", "correct": true, "because": "z. B. 2001:db8::/64 ist CIDR-Standard"}, {"text": "Nein", "correct": false, "because": "CIDR ist die Norm"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Präfixlänge bei der IPv6-Adresszuweisung mit SLAAC immer /64 sein?', 2, '[{"text": "Ja", "correct": true, "because": "SLAAC erfordert /64 für Interface-IDs"}, {"text": "Nein", "correct": false, "because": "/64 ist zwingend für SLAAC"}]'),
('00000000-0000-0000-0000-000000000000', 'Können mehrere Subnetze aus einem /48-Präfix erstellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "z. B. 65.536 /64-Subnetze möglich"}, {"text": "Nein", "correct": false, "because": "Subnetzierung ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Präfixlänge von /56 für ein kleines Unternehmensnetzwerk geeignet?', 2, '[{"text": "Ja", "correct": true, "because": "Bietet 256 /64-Subnetze"}, {"text": "Nein", "correct": false, "because": "/56 ist praktikabel"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits bleiben für die Interface-ID bei einer Präfixlänge von /56?', 2, '[{"text": "72 Bits", "correct": true, "because": "128 - 56 = 72 Bits"}, {"text": "64 Bits", "correct": false, "because": "Das ist bei /64"}, {"text": "48 Bits", "correct": false, "because": "Das ist bei /80"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Präfixlänge wird typischerweise einem einzelnen Gerät wie einem Router zugewiesen?', 3, '[{"text": "/128", "correct": true, "because": "Definiert eine einzelne Adresse"}, {"text": "/64", "correct": false, "because": "Für Subnetze"}, {"text": "/48", "correct": false, "because": "Für Organisationen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele /64-Subnetze können aus einem /60-Präfix erstellt werden?', 2, '[{"text": "16", "correct": true, "because": "2^(64-60) = 16"}, {"text": "8", "correct": false, "because": "Zu niedrig"}, {"text": "32", "correct": false, "because": "Zu hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Präfixlänge wird von Internetanbietern oft für ein Heimnetzwerk vergeben?', 2, '[{"text": "/56", "correct": true, "because": "Bietet 256 /64-Subnetze"}, {"text": "/64", "correct": false, "because": "Nur ein Subnetz"}, {"text": "/48", "correct": false, "because": "Für größere Netze"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert mit der Anzahl der Subnetze, wenn die Präfixlänge von /48 auf /52 erhöht wird?', 2, '[{"text": "Sie nimmt ab", "correct": true, "because": "Weniger Bits für Subnetze (65.536 zu 256)"}, {"text": "Sie bleibt gleich", "correct": false, "because": "Änderung beeinflusst Anzahl"}, {"text": "Sie erhöht sich", "correct": false, "because": "Falsche Richtung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Präfixlängen sind für verschiedene Netzwerkgrößen typisch?', 4, '[{"text": "/128 für einzelne Geräte", "correct": true, "because": "Eine Adresse"}, {"text": "/64 für Subnetze", "correct": true, "because": "Standard für SLAAC"}, {"text": "/48 für Organisationen", "correct": true, "because": "65.536 Subnetze"}, {"text": "/24 für Heimnetzwerke", "correct": false, "because": "IPv4, nicht IPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat eine Präfixlänge von /64?', 3, '[{"text": "Geeignet für SLAAC", "correct": true, "because": "64 Bits für Interface-ID"}, {"text": "2^64 mögliche Adressen", "correct": true, "because": "Enorme Adresszahl"}, {"text": "256 Subnetze aus /56", "correct": false, "because": "Das ist /56 zu /64"}, {"text": "Standard für Subnetze", "correct": true, "because": "Weit verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen hat eine Änderung der Präfixlänge von /56 auf /60?', 4, '[{"text": "Weniger Subnetze", "correct": true, "because": "256 zu 16 Subnetze"}, {"text": "Mehr Adressen pro Subnetz", "correct": false, "because": "Adressen bleiben gleich"}, {"text": "Kleinere Interface-ID", "correct": false, "because": "ID-Größe unverändert"}, {"text": "Weniger Flexibilität", "correct": true, "because": "Weniger Subnetzoptionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Wahl der IPv6-Präfixlänge?', 3, '[{"text": "Netzwerkgröße", "correct": true, "because": "Bestimmt Subnetzanzahl"}, {"text": "Adressierungsstrategie", "correct": true, "because": "z. B. SLAAC oder DHCPv6"}, {"text": "Anbieterzuweisung", "correct": true, "because": "z. B. /56 oder /48"}, {"text": "Betriebssystemtyp", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Präfixlängen könnten in einem Unternehmensnetzwerk sinnvoll sein?', 3, '[{"text": "/48", "correct": true, "because": "Viele Subnetze möglich"}, {"text": "/56", "correct": true, "because": "Für kleinere Abteilungen"}, {"text": "/64", "correct": true, "because": "Für einzelne Subnetze"}, {"text": "/32", "correct": false, "because": "Zu groß für typische Netze"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine /64-Präfixlänge ist für SLAAC erforderlich. b) Eine /128-Präfixlänge erlaubt mehrere Subnetze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SLAAC ja, /128 nur eine Adresse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine /56-Präfixlänge bietet 256 /64-Subnetze. b) Eine /48-Präfixlänge ist für ein Heimnetzwerk typisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "256 ja, /48 eher für Firmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine /60-Präfixlänge bietet 16 /64-Subnetze. b) Eine /64-Präfixlänge ist für DHCPv6 ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "16 ja, /64 auch für DHCPv6"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Präfixlänge bestimmt die Anzahl der Subnetze. b) Eine /128-Präfixlänge ist für Subnetze geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Subnetzanzahl ja, /128 keine Subnetze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine /48-Präfixlänge ermöglicht 65.536 /64-Subnetze. b) Die Präfixlänge beeinflusst die Adresszuweisung.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "65.536 ja, Zuweisung betroffen"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

